using GraphApi.Models.NTF.NotificacionesVisualizadas;namespace GraphApi.Services.NTF.NotificacionesVisualizadas{    /// <summary>    /// Define las operaciones de negocio y persistencia para NotificacionesVisualizadas.    /// </summary>    public interface INotificacionesVisualizadasService    {        /// <summary>        /// Obtiene la lista de NotificacionesVisualizadas con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadNotificacionesVisualizadas>> GetNotificacionesVisualizadas(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de NotificacionesVisualizadas con filtros opcionales.        /// </summary>        /// <param name="notificacionVisualizadaID">Filtro opcional para NotificacionVisualizadaID.</param>        /// <param name="notificacionID">Filtro opcional para NotificacionID.</param>        /// <param name="usuarioID">Filtro opcional para UsuarioID.</param>        /// <param name="fechaLectura">Filtro opcional para FechaLectura.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetNotificacionesVisualizadasDynamic(            int? notificacionVisualizadaID,            int? notificacionID,            int? usuarioID,            DateTime? fechaLectura,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo NotificacionesVisualizada.        /// </summary>        /// <param name="objInput">Datos para crear el NotificacionesVisualizada.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadNotificacionesVisualizadas> CreateNotificacionesVisualizadas(            clCreateNotificacionesVisualizadas objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un NotificacionesVisualizada.        /// </summary>        /// <param name="objInput">Datos para actualizar el NotificacionesVisualizada, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadNotificacionesVisualizadas?> UpdateNotificacionesVisualizadas(            clUpdateNotificacionesVisualizadas objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un NotificacionesVisualizada por su ID.        /// </summary>        /// <param name="nNotificacionesVisualizadasID">ID del NotificacionesVisualizada a eliminar.</param>        Task<bool> DeleteNotificacionesVisualizadas(int nNotificacionesVisualizadasID);    }}